
import { VPopup, TextBox, VIcon, VButton } from '@/ui'

export default Vue.extend({
  components: {
    VPopup,
    TextBox,
    VIcon,
    VButton,
  },
  props: {
    triggerElement: {
      type: HTMLElement,
      default: null,
    },
    list: {
      type: Array,
      default: null,
    },
    save: {
      type: Function,
      default: undefined,
    },
    titleName: {
      type: String,
      default: '',
    },
  },
  data() {
    return {
      open: false,
      loaded: false,
      name: '',
    }
  },
  watch: {
    open(newVal: boolean) {
      if (!newVal) {
        this.save(this.list)
      }
    },
  },
  async mounted() {
    this.loaded = true
  },
  methods: {
    toggle() {
      this.$refs.popup.toggle()
    },
    changeName(val: string) {
      this.name = val
    },
    add() {
      // eslint-disable-next-line vue/no-mutating-props
      this.list.push(this.name)
      // eslint-disable-next-line vue/no-mutating-props
      this.list = lodash.uniq(this.list)
      this.name = ''
    },
    toggleVisible(item: any) {
      // eslint-disable-next-line vue/no-mutating-props
      this.list.splice(this.list.indexOf(item), 1)
    },
  },
})
