
export default Vue.extend({
  name: 'SwitchBox',
  model: {
    prop: 'checked',
    event: 'change',
  },
  props: {
    checked: {
      type: Boolean,
      default: false,
    },
    disabled: {
      type: Boolean,
      default: false,
    },
  },
  methods: {
    toggle() {
      if (this.disabled) {
        return
      }
      this.$refs.input.checked = !this.$refs.input.checked
      this.$emit('change', this.$refs.input.checked)
    },
  },
})
