
import { installFeature, installFeatureFromCode } from '@/core/install-feature'
import { pickFile } from '@/core/file-picker'
import { Toast, ToastType } from '@/core/toast'
import { logError } from '@/core/utils/log'
import { FflateLibrary } from '@/core/runtime-library'
import { VIcon, VButton, TextBox, VEmpty, VLoading, VPopup, TextArea, SwitchBox } from '@/ui'
import ManageItem from './ManageItem.vue'
import OnlineRegistryButton from '../online-registry/OnlineRegistryButton.vue'

export default Vue.extend({
  components: {
    VIcon,
    VButton,
    TextBox,
    VEmpty,
    VLoading,
    VPopup,
    TextArea,
    SwitchBox,
    ManageItem,
    OnlineRegistryButton,
  },
  props: {
    config: {
      type: Object,
      required: true,
    },
  },
  data() {
    return {
      search: '',
      url: '',
      loaded: false,
      batchAddShow: false,
      batchUrl: '',
      excludeBuiltIn: true,
      debouncedList: [],
    }
  },
  computed: {
    filteredList() {
      return this.config.list.filter(it =>
        this.config.listFilter(it, this.search, this.excludeBuiltIn),
      )
    },
  },
  watch: {
    filteredList() {
      this.loaded = false
      window.setTimeout(() => {
        this.debouncedList = this.filteredList
        this.loaded = true
      }, 200)
    },
  },
  mounted() {
    window.setTimeout(() => {
      this.debouncedList = this.filteredList
      this.loaded = true
    })
  },
  methods: {
    async browse() {
      const codes = await pickFile({ accept: '*.js;*.zip' })
      if (codes.length === 0) {
        return
      }
      const [codeFile] = codes
      let code: string
      if (codeFile.name.endsWith('.zip')) {
        const fflate = await FflateLibrary
        const buffer = new Uint8Array(await codeFile.arrayBuffer())
        const files = await new Promise<Record<string, Uint8Array>>((resolve, reject) => {
          fflate.unzip(buffer, (err, data) => {
            if (err) {
              reject(err)
            } else {
              resolve(data)
            }
          })
        })
        const fileNames = Object.keys(files)
        if (fileNames.length === 0) {
          Toast.info('不能打开空文件', `添加${this.config.title}`)
          return
        }
        code = new TextDecoder().decode(files[fileNames[0]])
      } else {
        code = await codeFile.text()
      }
      try {
        const { message } = await installFeatureFromCode(code, '')
        Toast.info(message, `添加${this.config.title}`)
      } catch (error) {
        logError(error)
      }
    },
    async showBatchAddPopup() {
      this.batchAddShow = !this.batchAddShow
      if (this.batchAddShow) {
        await this.$nextTick()
        this.$refs.batchAddTextArea?.focus()
      }
    },
    async addItem() {
      if (!this.url) {
        return
      }
      const toast = Toast.info('获取中...', `添加${this.config.title}`)
      try {
        const { message } = await installFeature(this.url)
        toast.message = message
        this.url = ''
      } catch (error) {
        console.error(error)
        toast.type = ToastType.Error
        toast.message = error
      }
    },
    async batchAddItem() {
      if (!this.batchUrl) {
        return
      }
      const urls = (this.batchUrl as string)
        .split('\n')
        .map(it => it.trim())
        .filter(it => it !== '')
      const toast = Toast.info(`获取中... (0/${urls.length})`, '批量添加')
      let completed = 0
      const results = await Promise.allSettled(
        urls.map(async url => {
          const { message } = await installFeature(url)
          completed++
          toast.message = `获取中... (${completed}/${urls.length})`
          return message
        }),
      )
      const successCount = results.filter(it => it.status === 'fulfilled').length
      const failCount = results.filter(it => it.status === 'rejected').length
      toast.message = `安装完成, 成功 ${successCount} 个, 失败 ${failCount} 个.`
      const resultsText = results
        .map((r, index) => {
          const suffix = urls[index]
          if (r.status === 'fulfilled') {
            return `${r.value} ${suffix}`
          }
          return `${r.reason} ${suffix}`
        })
        .join('\n')
      console.log(resultsText)
      this.batchUrl = ''
    },
  },
})
