
import { getVideoCoverUrlByAid } from '@/components/video/video-cover'
import { videoChange } from '@/core/observer'

export default Vue.extend({
  data() {
    return {
      imageUrl: '',
    }
  },
  created() {
    videoChange(async () => {
      const { aid } = unsafeWindow
      this.imageUrl = await getVideoCoverUrlByAid(aid)
    })
  },
})
