
export default Vue.extend({
  name: 'VButton',
  props: {
    type: {
      type: String,
      default: 'light',
    },
    round: {
      type: Boolean,
      default: false,
    },
    icon: {
      type: Boolean,
      default: false,
    },
    noEffects: {
      type: Boolean,
      default: false,
    },
  },
  computed: {
    disabled() {
      return Boolean(this.$attrs.disabled)
    },
  },
})
